package main

import "sync"

type Account struct{ Balance int64 }

var (
	mu       sync.RWMutex
	accounts = map[int]*Account{1: {Balance: 100}}
)

func AddFunds() {
	mu.Lock()
	accounts[1].Balance++
	mu.Unlock()
}

func ReadBalance() int64 {
	mu.RLock()
	acc := accounts[1]
	balance := acc.Balance
	mu.RUnlock()
	return balance
}

func main() {
	var wg sync.WaitGroup
	wg.Add(2)
	go func() {
		defer wg.Done()
		for n := 0; n < 1000; n++ {
			AddFunds()
		}
	}()
	go func() {
		defer wg.Done()
		for n := 0; n < 1000; n++ {
			_ = ReadBalance()
		}
	}()
	wg.Wait()
}

