package main

import (
	"sync"
	"testing"
)

func TestConcurrentBalanceSnapshot(t *testing.T) {
	accounts = map[int]*Account{1: {Balance: 100}}
	var wg sync.WaitGroup
	wg.Add(2)
	go func() {
		defer wg.Done()
		for n := 0; n < 1000; n++ {
			AddFunds()
		}
	}()
	go func() {
		defer wg.Done()
		for n := 0; n < 1000; n++ {
			if v := ReadBalance(); v < 100 || v > 1100 {
				t.Errorf("out-of-range snapshot %d", v)
			}
		}
	}()
	wg.Wait()
	if got := ReadBalance(); got != 1100 {
		t.Fatalf("got %d, want 1100", got)
	}
}

