package quizcheck

import (
	"context"
	"os/exec"
	"sort"
	"strings"
	"testing"
	"time"
)

func TestLoopLanguageVersions(t *testing.T) {
	for _, tt := range []struct{ name, dir, language, want string }{
		{"original_125", "q1original", "go1.25", "0 1 2"},
		{"original_126", "q1original", "go1.26", "0 1 2"},
		{"original_117_rules", "q1original", "go1.17", "3 3 3"},
		{"explicit_argument_117_rules", "q1fixed", "go1.17", "0 1 2"},
		{"explicit_argument_126", "q1fixed", "go1.26", "0 1 2"},
		{"shared_assignment_126", "q1shared", "go1.26", "3 3 3"},
	} {
		t.Run(tt.name, func(t *testing.T) {
			ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
			defer cancel()
			out, err := exec.CommandContext(ctx, "go", "run", "-race", "-gcflags=-lang="+tt.language, "./cmd/"+tt.dir).CombinedOutput()
			fields := strings.Fields(string(out))
			sort.Strings(fields)
			if err != nil || strings.Join(fields, " ") != tt.want {
				t.Fatalf("%s: %v", out, err)
			}
		})
	}
}

func TestUnprotectedBalanceDetected(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	out, err := exec.CommandContext(ctx, "go", "run", "-race", "./cmd/q14original").CombinedOutput()
	if err == nil || !strings.Contains(string(out), "WARNING: DATA RACE") || !strings.Contains(string(out), "ReadBalance") {
		t.Fatalf("expected race at ReadBalance: %s %v", out, err)
	}
}

func TestProtectedBalanceProgram(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	out, err := exec.CommandContext(ctx, "go", "run", "-race", "./cmd/q14fixed").CombinedOutput()
	if err != nil || len(out) != 0 {
		t.Fatalf("fixed program: %s %v", out, err)
	}
}

fixtures.transactions_test.go:
package quizcheck

import (
	"context"
	"database/sql"
	"database/sql/driver"
	"errors"
	"reflect"
	"sync"
	"testing"
	"time"

	fixed "quizcheck/txfixed"
	original "quizcheck/txoriginal"
)

var errBegin = errors.New("begin failed")
var errExec = errors.New("exec failed")
var errCommit = errors.New("commit failed")
var errRollback = errors.New("rollback failed")

type trace struct {
	mu                                        sync.Mutex
	events                                    []string
	beginErr, execErr, commitErr, rollbackErr error
	panicExec                                 bool
	rolledBack                                chan struct{}
}

func (s *trace) add(event string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.events = append(s.events, event)
}
func (s *trace) snapshot() []string {
	s.mu.Lock()
	defer s.mu.Unlock()
	return append([]string(nil), s.events...)
}

type connector struct{ s *trace }

func (c connector) Connect(context.Context) (driver.Conn, error) { return &conn{c.s}, nil }
func (c connector) Driver() driver.Driver                        { return testDriver{} }

type testDriver struct{}

func (testDriver) Open(string) (driver.Conn, error) { return nil, errors.New("use connector") }

type conn struct{ s *trace }

func (c *conn) Prepare(string) (driver.Stmt, error) { return nil, errors.New("not used") }
func (c *conn) Close() error                        { return nil }
func (c *conn) Begin() (driver.Tx, error)           { return c.BeginTx(context.Background(), driver.TxOptions{}) }
func (c *conn) BeginTx(context.Context, driver.TxOptions) (driver.Tx, error) {
	c.s.add("begin")
	if c.s.beginErr != nil {
		return nil, c.s.beginErr
	}
	return &transaction{c.s}, nil
}
func (c *conn) ExecContext(ctx context.Context, query string, args []driver.NamedValue) (driver.Result, error) {
	c.s.add("exec")
	if query != "UPDATE tasks SET status = $1 WHERE id = $2" || len(args) != 2 || args[0].Value != "ready" || args[1].Value != int64(7) {
		return nil, errors.New("unexpected SQL or args")
	}
	if c.s.panicExec {
		panic("exec panic")
	}
	if c.s.execErr != nil {
		return nil, c.s.execErr
	}
	return driver.RowsAffected(1), nil
}

type transaction struct{ s *trace }

func (tx *transaction) Commit() error { tx.s.add("commit"); return tx.s.commitErr }
func (tx *transaction) Rollback() error {
	tx.s.add("rollback")
	close(tx.s.rolledBack)
	return tx.s.rollbackErr
}

func database(t *testing.T, s *trace) *sql.DB {
	t.Helper()
	s.rolledBack = make(chan struct{})
	db := sql.OpenDB(connector{s})
	db.SetMaxOpenConns(1)
	t.Cleanup(func() { db.Close() })
	return db
}
func requireEvents(t *testing.T, s *trace, want ...string) {
	t.Helper()
	if got := s.snapshot(); !reflect.DeepEqual(got, want) {
		t.Fatalf("events %v, want %v", got, want)
	}
}
func awaitRollback(t *testing.T, s *trace) {
	t.Helper()
	select {
	case <-s.rolledBack:
	case <-time.After(5 * time.Second):
		t.Fatal("rollback did not complete")
	}
}

func TestFixedTransactionPaths(t *testing.T) {
	for _, tt := range []struct {
		name    string
		state   *trace
		wantErr error
		events  []string
	}{
		{"success", &trace{}, nil, []string{"begin", "exec", "commit"}},
		{"begin failure", &trace{beginErr: errBegin}, errBegin, []string{"begin"}},
		{"exec failure", &trace{execErr: errExec}, errExec, []string{"begin", "exec", "rollback"}},
		{"commit failure", &trace{commitErr: errCommit}, errCommit, []string{"begin", "exec", "commit"}},
		{"rollback failure keeps primary error", &trace{execErr: errExec, rollbackErr: errRollback}, errExec, []string{"begin", "exec", "rollback"}},
	} {
		t.Run(tt.name, func(t *testing.T) {
			db := database(t, tt.state)
			got := fixed.UpdateStatus(context.Background(), db, 7, "ready")
			if !errors.Is(got, tt.wantErr) {
				t.Fatalf("error %v, want %v", got, tt.wantErr)
			}
			requireEvents(t, tt.state, tt.events...)
			if db.Stats().InUse != 0 {
				t.Fatal("connection still in use")
			}
		})
	}
}

func TestOriginalDeferSkipsRollbackUntilCancellation(t *testing.T) {
	s := &trace{execErr: errExec}
	db := database(t, s)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	if got := original.UpdateStatus(ctx, db, 7, "ready"); !errors.Is(got, errExec) {
		t.Fatal(got)
	}
	requireEvents(t, s, "begin", "exec")
	if db.Stats().InUse != 1 {
		t.Fatal("expected unclosed transaction")
	}
	cancel()
	awaitRollback(t, s)
	requireEvents(t, s, "begin", "exec", "rollback")
}

func TestFixedRollbackDuringPanicUnwind(t *testing.T) {
	s := &trace{panicExec: true}
	db := database(t, s)
	func() {
		defer func() {
			if recover() != "exec panic" {
				t.Error("expected panic")
			}
		}()
		fixed.UpdateStatus(context.Background(), db, 7, "ready")
	}()
	requireEvents(t, s, "begin", "exec", "rollback")
	if db.Stats().InUse != 0 {
		t.Fatal("connection retained after panic")
	}
}

func TestRollbackAfterCommitReturnsErrTxDone(t *testing.T) {
	s := &trace{}
	db := database(t, s)
	tx, err := db.BeginTx(context.Background(), nil)
	if err != nil {
		t.Fatal(err)
	}
	if err = tx.Commit(); err != nil {
		t.Fatal(err)
	}
	if err = tx.Rollback(); !errors.Is(err, sql.ErrTxDone) {
		t.Fatalf("got %v", err)
	}
	requireEvents(t, s, "begin", "commit")
}

