package example

import (
	"context"
	"database/sql"
)

func UpdateStatus(ctx context.Context, db *sql.DB, id int64, status string) error {
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer func(e error) {
		if e != nil {
			_ = tx.Rollback()
		}
	}(err)

	_, err = tx.ExecContext(ctx,
		"UPDATE tasks SET status = $1 WHERE id = $2", status, id)
	if err != nil {
		return err
	}
	return tx.Commit()
}
